UPDATE ai_model_usage_detail
SET conversation_message_id = #{conversationMessageId,jdbcType=BIGINT},
    upstream_request_id = #{upstreamRequestId,jdbcType=VARCHAR},
    settlement_delta_minor = #{settlementDeltaMinor,jdbcType=BIGINT}
WHERE usage_id = #{usageId,jdbcType=BINARY}

WITH candidate(usage_id, reserved_quota_minor) AS ( VALUES
( #{candidate.usageId,jdbcType=BINARY}, #{candidate.reservedQuotaMinor,jdbcType=BIGINT} )
) UPDATE ai_model_usage_detail detail SET settlement_delta_minor = -candidate.reserved_quota_minor FROM candidate WHERE detail.usage_id = candidate.usage_id AND detail.conversation_message_id IS NULL AND detail.settlement_delta_minor IS NULL
